CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_completar_datos_masivos`()
BEGIN
    DECLARE v_users_actuales INT;
    DECLARE v_products_actuales INT;
    DECLARE i INT;

    SELECT COUNT(*) INTO v_users_actuales FROM `db_test_7b`.`tb_users`;
    SELECT COUNT(*) INTO v_products_actuales FROM `db_test_7b`.`tb_products`;

    -- Completar hasta 7,500 usuarios
    SET i = v_users_actuales + 1;
    WHILE i <= 7500 DO
        INSERT IGNORE INTO `db_test_7b`.`tb_users` (`email`, `nick`, `password`, `status`)
        VALUES (
            CONCAT('usuario_seed_', i, '@ecommerce7b.com'),
            CONCAT('user_seed_', i),
            SHA2(CONCAT('Pass7B_', i), 256),
            b'1'
        );
        SET i = i + 1;
    END WHILE;

    -- Completar hasta 7,000 productos
    SET i = v_products_actuales + 1;
    WHILE i <= 7000 DO
        INSERT IGNORE INTO `db_test_7b`.`tb_products` (`name`, `description`, `current_price`, `stock`, `status`)
        VALUES (
            CONCAT('Producto Catálogo #', i),
            CONCAT('Descripción técnica del artículo número ', i),
            ROUND(50 + (RAND() * 2450), 2),
            FLOOR(10 + (RAND() * 190)),
            b'1'
        );
        SET i = i + 1;
    END WHILE;
END ;;
